foreach($regexFrom as $idx => $from){
    $from = trim((string)$from);
    if($from === '' || mb_strlen($from) > 512) continue;
    if(preg_match('#[eE]\\s*$#', $from) || stripos($from, 'e') === mb_strlen($from) - 2) continue;
    if(@preg_match($from, '') === false) continue;
    $regexRules[] = ['FROM' => $from, 'TO' => trim((string)($regexTo[$idx] ?? ''))];
}

